INSERT INTO `terms` (`termId`, `categoryRef`, `status`, `isFeatured`, `content`) VALUES
(2, 5, 'published', 1, CAST('{"default":{"en":{"name":"Causal Layered Analysis","briefDescription":"A futures framework by Sohail Inayatullah that explores diverse perspectives to understand complex issues and envision alternative futures.","fullDescription":"Causal Layered Analysis (CLA) examines an issue at four layers: the litany (visible events and data), social causes, worldview or discourse, and myth or metaphor. Moving between the layers reveals deeper assumptions and opens space for genuinely different futures.","references":[{"content":"Inayatullah, S. (1998). Causal layered analysis: Poststructuralism as method. Futures, 30(8), 815–829."}]},"ar":{"name":"التحليل الطبقي السببي","briefDescription":"إطار مستقبلي طوّره سهيل عناية الله لاستكشاف وجهات نظر متعددة بهدف فهم القضايا المعقدة وتصوّر مستقبلات بديلة.","fullDescription":"يحلّل التحليل الطبقي السببي القضية على أربع طبقات: الظاهر (الأحداث والبيانات المرئية)، والأسباب الاجتماعية، والرؤية الكونية أو الخطاب، والأسطورة أو الاستعارة. ويكشف التنقل بين هذه الطبقات الافتراضات العميقة ويفتح المجال لمستقبلات مختلفة حقًا."}},"more":[]}' AS JSON)),
(3, 5, 'published', 1, CAST('{"default":{"en":{"name":"Scenario Planning","briefDescription":"A method for developing several plausible stories about how the future could unfold, used to test strategies against uncertainty.","fullDescription":"Scenario planning identifies the key drivers and critical uncertainties shaping an issue, then builds a small set of contrasting, internally consistent narratives. Decision-makers use these scenarios to rehearse responses and design strategies that remain robust across different futures.","references":[{"content":"Schwartz, P. (1991). The Art of the Long View. New York: Doubleday."}]},"ar":{"name":"التخطيط بالسيناريوهات","briefDescription":"منهج لبناء عدة قصص معقولة حول الطرق التي قد يتكشّف بها المستقبل، يُستخدم لاختبار الاستراتيجيات في ظل عدم اليقين.","fullDescription":"يحدّد التخطيط بالسيناريوهات المحركات الرئيسية وأوجه عدم اليقين الحرجة المؤثرة في قضية ما، ثم يبني مجموعة صغيرة من السرديات المتباينة والمتسقة داخليًا. ويستخدمها صنّاع القرار للتمرّن على الاستجابات وتصميم استراتيجيات تصمد عبر مستقبلات مختلفة."}},"more":[]}' AS JSON)),
(4, 5, 'published', 1, CAST('{"default":{"en":{"name":"Delphi Method","briefDescription":"A structured process that gathers expert judgement through several anonymous rounds of questionnaires to converge on informed forecasts.","fullDescription":"In a Delphi study, a panel of experts answers questionnaires in successive rounds. After each round a facilitator shares an anonymised summary, allowing participants to revise their views. The anonymity reduces the influence of dominant voices while the iteration builds a considered collective judgement.","references":[{"content":"Dalkey, N., & Helmer, O. (1963). An experimental application of the Delphi method to the use of experts. Management Science, 9(3), 458–467."}]},"ar":{"name":"طريقة دلفي","briefDescription":"عملية منظّمة لجمع آراء الخبراء عبر عدة جولات مجهولة الهوية من الاستبيانات للوصول إلى تقديرات مستنيرة.","fullDescription":"في دراسة دلفي يجيب فريق من الخبراء عن استبيانات في جولات متتالية، ويعرض الميسّر بعد كل جولة ملخصًا مجهول الهوية يتيح للمشاركين مراجعة آرائهم. ويقلّل إخفاء الهوية من هيمنة الأصوات المسيطرة، بينما يبني التكرار حكمًا جماعيًا متأنيًا."}},"more":[]}' AS JSON)),
(5, 5, 'published', 0, CAST('{"default":{"en":{"name":"Horizon Scanning","briefDescription":"The systematic search for early signs of change, emerging issues and trends that could matter for the future.","fullDescription":"Horizon scanning looks beyond the usual sources and time frames to detect developments at the edge of current awareness. Its outputs feed foresight work by flagging what deserves monitoring, deeper analysis or early action."},"ar":{"name":"مسح الأفق","briefDescription":"البحث المنهجي عن المؤشرات المبكرة للتغيير والقضايا الناشئة والاتجاهات التي قد تكون مهمة للمستقبل.","fullDescription":"يتجاوز مسح الأفق المصادر والأطر الزمنية المعتادة لرصد التطورات الواقعة على أطراف الوعي الحالي، وتغذّي مخرجاته عمل الاستشراف بتحديد ما يستحق المتابعة أو التحليل المعمّق أو التحرك المبكر."}},"more":[]}' AS JSON)),
(6, 5, 'published', 0, CAST('{"default":{"en":{"name":"Futures Wheel","briefDescription":"A visual brainstorming tool that maps the direct and indirect consequences of a change or trend in concentric rings.","fullDescription":"A central event or trend is placed in the middle; first-order consequences radiate outward, followed by second- and third-order effects. The wheel makes chains of impact visible and helps groups think beyond immediate, obvious outcomes.","references":[{"content":"Glenn, J. C. (1972). Futurizing teaching vs. futures course. Social Science Record, 9(3), 26–29."}]},"ar":{"name":"عجلة المستقبلات","briefDescription":"أداة بصرية للعصف الذهني ترسم النتائج المباشرة وغير المباشرة لتغيّر أو اتجاه ما في حلقات متحدة المركز.","fullDescription":"يوضع الحدث أو الاتجاه في المركز، وتتفرع منه النتائج من الدرجة الأولى ثم آثار الدرجتين الثانية والثالثة. وتجعل العجلة سلاسل التأثير مرئية وتساعد المجموعات على التفكير فيما يتجاوز النتائج الفورية الواضحة."}},"more":[]}' AS JSON)),
(7, 5, 'published', 0, CAST('{"default":{"en":{"name":"Backcasting","briefDescription":"A planning approach that starts from a desired future and works backwards to identify the steps needed to reach it.","fullDescription":"Rather than extrapolating from today, backcasting defines a preferred end state and then asks which policies, actions and milestones would connect the present to that future. It is widely used in sustainability and energy transitions.","references":[{"content":"Robinson, J. B. (1982). Energy backcasting: A proposed method of policy analysis. Energy Policy, 10(4), 337–344."}]},"ar":{"name":"الاستشراف العكسي","briefDescription":"مقاربة تخطيطية تنطلق من مستقبل مرغوب ثم تعود إلى الوراء لتحديد الخطوات اللازمة للوصول إليه.","fullDescription":"بدلًا من الاستقراء انطلاقًا من الحاضر، يحدّد الاستشراف العكسي حالة نهائية مفضّلة ثم يسأل عن السياسات والإجراءات والمحطات التي تربط الحاضر بذلك المستقبل، ويُستخدم على نطاق واسع في التحولات المستدامة وتحولات الطاقة."}},"more":[]}' AS JSON)),
(8, 5, 'published', 0, CAST('{"default":{"en":{"name":"Three Horizons","briefDescription":"A framework that maps the decline of today\'s dominant system, the transitional innovations, and the emerging patterns of a viable future.","fullDescription":"Horizon 1 is the current way of doing things, gradually losing fit; Horizon 3 holds the seeds of a new pattern; Horizon 2 is the contested space of transition between them. The framework helps groups hold the present and the long term in the same conversation.","references":[{"content":"Sharpe, B. (2013). Three Horizons: The Patterning of Hope. Axminster: Triarchy Press."}]},"ar":{"name":"نموذج الآفاق الثلاثة","briefDescription":"إطار يرسم تراجع النظام السائد اليوم، والابتكارات الانتقالية، والأنماط الناشئة لمستقبل قابل للحياة.","fullDescription":"يمثّل الأفق الأول الطريقة الحالية في العمل التي تفقد ملاءمتها تدريجيًا، ويحمل الأفق الثالث بذور نمط جديد، أما الأفق الثاني فهو المساحة المتنازع عليها للانتقال بينهما. ويساعد الإطار على جمع الحاضر والمدى البعيد في حوار واحد."}},"more":[]}' AS JSON)),
(9, 5, 'published', 0, CAST('{"default":{"en":{"name":"Futures Triangle","briefDescription":"A tool that maps the competing forces of the pull of the future, the push of the present and the weight of history.","fullDescription":"The futures triangle places images of the future (pull), current drivers and trends (push) and historical barriers to change (weight) at three corners. Analysing the tension between them shows which futures are plausible and where change can be leveraged.","references":[{"content":"Inayatullah, S. (2008). Six pillars: futures thinking for transforming. Foresight, 10(1), 4–21."}]},"ar":{"name":"مثلث المستقبلات","briefDescription":"أداة ترسم القوى المتنافسة: جذب المستقبل، ودفع الحاضر، وثقل التاريخ.","fullDescription":"يضع مثلث المستقبلات صور المستقبل (الجذب) والمحركات والاتجاهات الحالية (الدفع) والعوائق التاريخية أمام التغيير (الثقل) في رؤوسه الثلاثة. ويُظهر تحليل التوتر بينها المستقبلات المعقولة ومواضع إمكانية إحداث التغيير."}},"more":[]}' AS JSON)),
(10, 5, 'published', 0, CAST('{"default":{"en":{"name":"Trend Analysis","briefDescription":"The study of patterns of change over time to understand their direction, speed and possible future development.","fullDescription":"Trend analysis gathers historical and current data on a phenomenon, identifies its trajectory and examines the forces sustaining or limiting it. It is most useful when combined with methods that consider discontinuities, since trends rarely continue unchanged."},"ar":{"name":"تحليل الاتجاهات","briefDescription":"دراسة أنماط التغيّر عبر الزمن لفهم اتجاهها وسرعتها وتطورها المحتمل في المستقبل.","fullDescription":"يجمع تحليل الاتجاهات بيانات تاريخية وحالية عن ظاهرة ما، ويحدد مسارها، ويدرس القوى التي تدعمها أو تحدّ منها. ويكون أكثر فائدة عند دمجه بمناهج تأخذ الانقطاعات في الحسبان، لأن الاتجاهات نادرًا ما تستمر دون تغيّر."}},"more":[]}' AS JSON)),
(11, 5, 'published', 0, CAST('{"default":{"en":{"name":"Cross-Impact Analysis","briefDescription":"A method that examines how the occurrence of one future event changes the likelihood of others.","fullDescription":"Events are arranged in a matrix and experts estimate how each one would raise or lower the probability of the rest. The analysis exposes interdependencies that single-event forecasts miss and helps build more coherent scenarios.","references":[{"content":"Gordon, T. J., & Hayward, H. (1968). Initial experiments with the cross impact matrix method of forecasting. Futures, 1(2), 100–116."}]},"ar":{"name":"تحليل التأثير المتبادل","briefDescription":"منهج يدرس كيف يغيّر وقوعُ حدث مستقبلي ما احتمالَ وقوع أحداث أخرى.","fullDescription":"تُرتّب الأحداث في مصفوفة ويقدّر الخبراء كيف يرفع كل حدث احتمال بقية الأحداث أو يخفضه. ويكشف التحليل الترابطات التي تغفلها التوقعات المبنية على حدث منفرد، ويساعد على بناء سيناريوهات أكثر اتساقًا."}},"more":[]}' AS JSON)),
(12, 5, 'published', 0, CAST('{"default":{"en":{"name":"Visioning","briefDescription":"A participatory process for articulating a shared, desirable image of the future that can guide action.","fullDescription":"Visioning invites people to describe in concrete terms the future they want to live in. A strong vision energises collective action and provides the destination from which strategies, and methods such as backcasting, can be developed."},"ar":{"name":"بناء الرؤى","briefDescription":"عملية تشاركية لصياغة صورة مشتركة ومرغوبة للمستقبل يمكنها توجيه العمل.","fullDescription":"يدعو بناء الرؤى المشاركين إلى وصف المستقبل الذي يريدون العيش فيه بعبارات ملموسة. وتمنح الرؤية القوية العمل الجماعي طاقة، وتوفّر الوجهة التي تُبنى انطلاقًا منها الاستراتيجيات ومناهج مثل الاستشراف العكسي."}},"more":[]}' AS JSON)),
(13, 5, 'published', 0, CAST('{"default":{"en":{"name":"STEEP Analysis","briefDescription":"A scanning framework that organises drivers of change into Social, Technological, Economic, Environmental and Political categories.","fullDescription":"STEEP gives horizon scanning a checklist so that no major domain of change is overlooked. Variants such as STEEPLE add Legal and Ethical factors. The categories are a starting point; the most interesting insights often sit in the interactions between them."},"ar":{"name":"تحليل STEEP","briefDescription":"إطار للمسح ينظّم محركات التغيير في فئات اجتماعية وتكنولوجية واقتصادية وبيئية وسياسية.","fullDescription":"يمنح إطار STEEP مسحَ الأفق قائمة مرجعية تضمن عدم إغفال أي مجال رئيسي من مجالات التغيير، وتضيف صيغ مثل STEEPLE العوامل القانونية والأخلاقية. والفئات نقطة انطلاق فقط، إذ كثيرًا ما تكمن أهم الرؤى في التفاعلات بينها."}},"more":[]}' AS JSON)),
(14, 5, 'published', 0, CAST('{"default":{"en":{"name":"Wind Tunnelling","briefDescription":"Testing a strategy or policy against several scenarios to see how well it performs in each.","fullDescription":"Like testing a model aircraft in a wind tunnel, a strategy is run through contrasting scenarios to reveal where it holds, where it breaks and what adjustments would make it more robust."},"ar":{"name":"اختبار نفق الرياح","briefDescription":"اختبار استراتيجية أو سياسة في مواجهة عدة سيناريوهات لمعرفة مدى نجاحها في كل منها.","fullDescription":"كما يُختبر نموذج طائرة في نفق الرياح، تُمرَّر الاستراتيجية عبر سيناريوهات متباينة لكشف مواضع صمودها ومواضع انهيارها والتعديلات التي تجعلها أكثر متانة."}},"more":[]}' AS JSON)),
(15, 5, 'published', 0, CAST('{"default":{"en":{"name":"Emerging Issues Analysis","briefDescription":"A method for identifying issues in their earliest stages, before they become trends or problems on the public agenda.","fullDescription":"Emerging issues analysis looks for ideas and developments that are still marginal, often found in niche publications, fringe groups or early research. Spotting them early gives organisations more time and options to respond.","references":[{"content":"Molitor, G. T. T. (1977). How to anticipate public-policy changes. SAM Advanced Management Journal, 42(3), 4–13."}]},"ar":{"name":"تحليل القضايا الناشئة","briefDescription":"منهج لتحديد القضايا في مراحلها الأولى قبل أن تتحول إلى اتجاهات أو مشكلات على جدول الأعمال العام.","fullDescription":"يبحث تحليل القضايا الناشئة عن أفكار وتطورات لا تزال هامشية، كثيرًا ما توجد في منشورات متخصصة أو مجموعات طرفية أو أبحاث مبكرة. ويمنح رصدها مبكرًا المؤسساتِ وقتًا وخيارات أكثر للاستجابة."}},"more":[]}' AS JSON)),
(16, 5, 'published', 0, CAST('{"default":{"en":{"name":"Morphological Analysis","briefDescription":"A method for exploring all possible combinations of the key parameters of a complex problem.","fullDescription":"The problem is broken into dimensions, each with several possible states. Combining one state from each dimension produces a configuration; screening out inconsistent combinations leaves a structured space of possibilities useful for scenario building and innovation.","references":[{"content":"Zwicky, F. (1969). Discovery, Invention, Research through the Morphological Approach. New York: Macmillan."}]},"ar":{"name":"التحليل المورفولوجي","briefDescription":"منهج لاستكشاف جميع التوليفات الممكنة للمعايير الأساسية لمشكلة معقدة.","fullDescription":"تُقسَّم المشكلة إلى أبعاد لكل منها حالات ممكنة عدة، ويُنتج الجمع بين حالة من كل بُعد تشكيلًا محددًا. وبعد استبعاد التوليفات غير المتسقة يبقى فضاء منظّم من الاحتمالات يفيد في بناء السيناريوهات والابتكار."}},"more":[]}' AS JSON)),
(17, 5, 'published', 0, CAST('{"default":{"en":{"name":"Roadmapping","briefDescription":"A planning technique that lays out the sequence of developments, capabilities and decisions needed to reach a long-term goal.","fullDescription":"Roadmaps connect a vision to time-bound milestones across layers such as markets, products and technologies. They make dependencies explicit and are often revisited as conditions change."},"ar":{"name":"خرائط الطريق","briefDescription":"تقنية تخطيطية ترسم تسلسل التطورات والقدرات والقرارات اللازمة لبلوغ هدف بعيد المدى.","fullDescription":"تربط خرائط الطريق الرؤية بمحطات زمنية محددة عبر طبقات مثل الأسواق والمنتجات والتقنيات، فتجعل الاعتمادات المتبادلة واضحة، وكثيرًا ما تُراجَع مع تغيّر الظروف."}},"more":[]}' AS JSON)),
(18, 5, 'published', 0, CAST('{"default":{"en":{"name":"Speculative Design","briefDescription":"A design practice that creates provocative artefacts and scenarios to question how things could be, rather than solve immediate problems.","fullDescription":"Speculative design uses prototypes, objects and fictional settings from possible futures to spark debate about values, technologies and choices. By making futures tangible it helps people react to them emotionally as well as intellectually.","references":[{"content":"Dunne, A., & Raby, F. (2013). Speculative Everything: Design, Fiction, and Social Dreaming. Cambridge, MA: MIT Press."}]},"ar":{"name":"التصميم التأملي","briefDescription":"ممارسة تصميمية تبتكر قطعًا وسيناريوهات مستفزة للتساؤل عمّا يمكن أن تكون عليه الأشياء، لا لحل مشكلات آنية.","fullDescription":"يستخدم التصميم التأملي نماذج أولية وأشياء وبيئات متخيَّلة من مستقبلات ممكنة لإثارة النقاش حول القيم والتقنيات والخيارات. وبجعله المستقبلات ملموسة يساعد الناس على التفاعل معها وجدانيًا وفكريًا."}},"more":[]}' AS JSON)),
(19, 6, 'published', 1, CAST('{"default":{"en":{"name":"Weak Signals","briefDescription":"Early, ambiguous indications of change that may grow into significant trends or disruptions.","fullDescription":"Weak signals are easy to dismiss because they are faint, scattered or seem odd. Collecting and interpreting them is central to anticipation, giving early warning of opportunities and threats before they are obvious.","references":[{"content":"Ansoff, H. I. (1975). Managing strategic surprise by response to weak signals. California Management Review, 18(2), 21–33."}]},"ar":{"name":"الإشارات الضعيفة","briefDescription":"مؤشرات مبكرة وغامضة على التغيير قد تتطور إلى اتجاهات أو اضطرابات مهمة.","fullDescription":"يسهل تجاهل الإشارات الضعيفة لأنها خافتة أو متفرقة أو تبدو غريبة، غير أن جمعها وتفسيرها أساسيان في الاستباق، إذ تقدّم إنذارًا مبكرًا بالفرص والتهديدات قبل أن تصبح واضحة."}},"more":[]}' AS JSON)),
(20, 6, 'published', 0, CAST('{"default":{"en":{"name":"Wild Card","briefDescription":"A low-probability, high-impact event that would dramatically change the course of the future if it occurred.","fullDescription":"Wild cards are used in foresight to stretch thinking and test the resilience of plans. Even if a specific wild card never happens, preparing for its kind of shock improves an organisation\'s readiness for surprise."},"ar":{"name":"البطاقة الجامحة","briefDescription":"حدث منخفض الاحتمال عالي الأثر من شأنه أن يغيّر مسار المستقبل جذريًا إن وقع.","fullDescription":"تُستخدم البطاقات الجامحة في الاستشراف لتوسيع آفاق التفكير واختبار صمود الخطط. وحتى إن لم تقع بطاقة بعينها، فإن الاستعداد لنوع الصدمة التي تمثّلها يعزز جاهزية المؤسسة لمواجهة المفاجآت."}},"more":[]}' AS JSON)),
(21, 6, 'published', 0, CAST('{"default":{"en":{"name":"Black Swan","briefDescription":"A rare, unpredictable event with extreme consequences that people rationalise as predictable only after it happens.","fullDescription":"The term, popularised by Nassim Nicholas Taleb, highlights the limits of forecasting based on past data. Foresight responds not by predicting black swans but by building systems that are robust, or even strengthened, under shocks.","references":[{"content":"Taleb, N. N. (2007). The Black Swan: The Impact of the Highly Improbable. New York: Random House."}]},"ar":{"name":"البجعة السوداء","briefDescription":"حدث نادر غير متوقع ذو عواقب جسيمة، يُفسَّر بعد وقوعه وكأنه كان قابلًا للتنبؤ.","fullDescription":"يسلّط المصطلح، الذي شاع على يد نسيم نيكولاس طالب، الضوء على حدود التنبؤ المبني على بيانات الماضي. ولا يسعى الاستشراف إلى التنبؤ بالبجعات السوداء، بل إلى بناء أنظمة تصمد أمام الصدمات أو حتى تقوى بها."}},"more":[]}' AS JSON)),
(22, 6, 'published', 0, CAST('{"default":{"en":{"name":"Megatrend","briefDescription":"A large-scale, long-term pattern of change that affects societies, economies and environments globally.","fullDescription":"Megatrends such as demographic ageing, urbanisation and climate change unfold over decades and are hard to reverse. They form the backdrop against which more specific trends and scenarios are explored.","references":[{"content":"Naisbitt, J. (1982). Megatrends: Ten New Directions Transforming Our Lives. New York: Warner Books."}]},"ar":{"name":"الاتجاه الكبير","briefDescription":"نمط تغيير واسع النطاق وطويل الأمد يؤثر في المجتمعات والاقتصادات والبيئات على المستوى العالمي.","fullDescription":"تتكشّف الاتجاهات الكبرى، مثل شيخوخة السكان والتحضّر وتغيّر المناخ، على مدى عقود ويصعب عكسها، وتشكّل الخلفية التي تُستكشف في ضوئها الاتجاهات والسيناريوهات الأكثر تحديدًا."}},"more":[]}' AS JSON)),
(23, 6, 'published', 0, CAST('{"default":{"en":{"name":"Driver of Change","briefDescription":"A force or factor that shapes how a system develops and pushes it in a particular direction.","fullDescription":"Drivers can be social, technological, economic, environmental or political. Identifying them, and judging their impact and uncertainty, is a core step in building scenarios."},"ar":{"name":"محرك التغيير","briefDescription":"قوة أو عامل يشكّل طريقة تطور نظام ما ويدفعه في اتجاه معيّن.","fullDescription":"قد تكون المحركات اجتماعية أو تكنولوجية أو اقتصادية أو بيئية أو سياسية، ويُعد تحديدها وتقدير أثرها ودرجة عدم اليقين فيها خطوة أساسية في بناء السيناريوهات."}},"more":[]}' AS JSON)),
(24, 6, 'published', 0, CAST('{"default":{"en":{"name":"Preferable Future","briefDescription":"A future that people judge to be desirable according to their values, as distinct from what is merely possible or probable.","fullDescription":"Distinguishing preferable futures from probable ones makes the normative dimension of foresight explicit: it asks not only what might happen, but what ought to happen and for whom."},"ar":{"name":"المستقبل المفضَّل","briefDescription":"مستقبل يراه الناس مرغوبًا وفق قيمهم، تمييزًا له عمّا هو ممكن أو محتمل فحسب.","fullDescription":"يجعل التمييز بين المستقبلات المفضّلة والمحتملة البعدَ المعياري للاستشراف صريحًا، فهو لا يسأل عمّا قد يحدث فحسب، بل عمّا ينبغي أن يحدث ولمن."}},"more":[]}' AS JSON)),
(25, 6, 'published', 0, CAST('{"default":{"en":{"name":"Futures Cone","briefDescription":"A diagram showing the widening range of possible, plausible, probable and preferable futures as time extends from the present.","fullDescription":"The cone illustrates that uncertainty grows with time and that futures can be classified by how possible, plausible or probable they are, and by whether they are preferable. It is a common teaching tool in futures literacy.","references":[{"content":"Voros, J. (2003). A generic foresight process framework. Foresight, 5(3), 10–21."}]},"ar":{"name":"مخروط المستقبلات","briefDescription":"مخطط يبيّن اتساع نطاق المستقبلات الممكنة والمعقولة والمحتملة والمفضّلة كلما ابتعدنا عن الحاضر.","fullDescription":"يوضّح المخروط أن عدم اليقين يتزايد مع الزمن، وأن المستقبلات يمكن تصنيفها بحسب إمكانيتها ومعقوليتها واحتمالها وكونها مفضّلة، وهو أداة تعليمية شائعة في محو أمية المستقبل."}},"more":[]}' AS JSON)),
(26, 6, 'published', 1, CAST('{"default":{"en":{"name":"Futures Literacy","briefDescription":"The capability to imagine and use the future to better understand the present and act in it.","fullDescription":"Promoted by UNESCO, futures literacy treats anticipation as a skill everyone can learn. It helps people question their assumptions about the future and use imagined futures to see new possibilities today.","references":[{"content":"Miller, R. (Ed.). (2018). Transforming the Future: Anticipation in the 21st Century. Paris: UNESCO / Routledge."}]},"ar":{"name":"محو أمية المستقبل","briefDescription":"القدرة على تخيّل المستقبل واستخدامه لفهم الحاضر بشكل أفضل والعمل فيه.","fullDescription":"تروّج اليونسكو لمحو أمية المستقبل بوصفه مهارة يمكن للجميع تعلّمها، فهو يساعد الناس على مساءلة افتراضاتهم حول المستقبل واستخدام المستقبلات المتخيَّلة لرؤية إمكانات جديدة اليوم."}},"more":[]}' AS JSON)),
(27, 6, 'published', 0, CAST('{"default":{"en":{"name":"Anticipation","briefDescription":"The use of ideas about the future to inform decisions and actions in the present.","fullDescription":"Anticipation studies examine how people, organisations and even living systems use models of the future. Foresight is one deliberate, structured form of anticipation.","references":[{"content":"Poli, R. (2017). Introduction to Anticipation Studies. Cham: Springer."}]},"ar":{"name":"الاستباق","briefDescription":"توظيف التصورات عن المستقبل في توجيه القرارات والأفعال في الحاضر.","fullDescription":"تدرس دراسات الاستباق كيف يستخدم الأفراد والمؤسسات وحتى الأنظمة الحية نماذج عن المستقبل، ويُعد الاستشراف أحد أشكال الاستباق المقصودة والمنظّمة."}},"more":[]}' AS JSON)),
(28, 6, 'published', 1, CAST('{"default":{"en":{"name":"Strategic Foresight","briefDescription":"The organised practice of exploring possible futures to inform strategy and decision-making today.","fullDescription":"Strategic foresight combines methods such as horizon scanning, scenarios and visioning to help organisations anticipate change, challenge assumptions and make choices that hold up across a range of futures."},"ar":{"name":"الاستشراف الاستراتيجي","briefDescription":"ممارسة منظّمة لاستكشاف المستقبلات الممكنة بهدف توجيه الاستراتيجية وصنع القرار اليوم.","fullDescription":"يجمع الاستشراف الاستراتيجي بين مناهج مثل مسح الأفق والسيناريوهات وبناء الرؤى لمساعدة المؤسسات على استباق التغيير ومساءلة افتراضاتها واتخاذ خيارات تصمد عبر طيف من المستقبلات."}},"more":[]}' AS JSON)),
(29, 6, 'published', 0, CAST('{"default":{"en":{"name":"Plausible Future","briefDescription":"A future that could happen given current knowledge of how the world works.","fullDescription":"Plausibility is judged against what is understood about systems and causality today. Scenario work usually aims for plausible rather than merely possible futures, so that stories are challenging yet credible."},"ar":{"name":"المستقبل المعقول","briefDescription":"مستقبل يمكن أن يحدث وفق المعرفة الحالية بطريقة عمل العالم.","fullDescription":"تُقاس المعقولية بما هو مفهوم اليوم عن الأنظمة والسببية، وعادةً ما يستهدف العمل على السيناريوهات المستقبلات المعقولة لا الممكنة فحسب، كي تكون القصص مثيرة للتحدي وذات مصداقية في آن."}},"more":[]}' AS JSON)),
(30, 6, 'published', 0, CAST('{"default":{"en":{"name":"Uncertainty","briefDescription":"The condition of not knowing how key factors will develop, which foresight seeks to explore rather than eliminate.","fullDescription":"Foresight distinguishes between risks that can be estimated and deeper uncertainties that cannot. Critical uncertainties, those with high impact and unclear direction, often become the axes of scenario sets."},"ar":{"name":"عدم اليقين","briefDescription":"حالة عدم معرفة كيفية تطور العوامل الرئيسية، وهي ما يسعى الاستشراف إلى استكشافه لا إزالته.","fullDescription":"يميّز الاستشراف بين المخاطر القابلة للتقدير وأوجه عدم اليقين الأعمق التي لا يمكن تقديرها. وكثيرًا ما تصبح أوجه عدم اليقين الحرجة، أي ذات الأثر الكبير والاتجاه غير الواضح، محاورَ لمجموعات السيناريوهات."}},"more":[]}' AS JSON)),
(31, 2, 'published', 0, CAST('{"default":{"en":{"name":"Path Dependency","briefDescription":"The way past decisions and events constrain the options available in the present and future.","fullDescription":"Once a technology, institution or practice is established, switching away from it can be costly, so early choices shape long-term trajectories. Recognising path dependency helps explain the \'weight of history\' in futures analysis."},"ar":{"name":"الاعتماد على المسار","briefDescription":"الطريقة التي تقيّد بها القرارات والأحداث الماضية الخيارات المتاحة في الحاضر والمستقبل.","fullDescription":"حين تترسّخ تقنية أو مؤسسة أو ممارسة يصبح التحول عنها مكلفًا، فتشكّل الخيارات المبكرة المسارات طويلة الأمد. ويساعد إدراك الاعتماد على المسار في تفسير «ثقل التاريخ» في تحليل المستقبلات."}},"more":[]}' AS JSON)),
(32, 6, 'published', 0, CAST('{"default":{"en":{"name":"Discontinuity","briefDescription":"A sharp break from established patterns, after which past trends no longer reliably describe the future.","fullDescription":"Discontinuities can be triggered by technological breakthroughs, crises or political shifts. Foresight pays special attention to them because trend-based planning is most likely to fail precisely when they occur."},"ar":{"name":"الانقطاع","briefDescription":"قطيعة حادة مع الأنماط الراسخة لا تعود بعدها اتجاهات الماضي وصفًا موثوقًا للمستقبل.","fullDescription":"قد تنشأ الانقطاعات عن اختراقات تكنولوجية أو أزمات أو تحولات سياسية، ويولي الاستشراف اهتمامًا خاصًا بها لأن التخطيط المبني على الاتجاهات هو الأكثر عرضة للإخفاق عند وقوعها تحديدًا."}},"more":[]}' AS JSON)),
(33, 6, 'published', 0, CAST('{"default":{"en":{"name":"Image of the Future","briefDescription":"A shared picture of what lies ahead that shapes how a society acts in the present.","fullDescription":"Fred Polak argued that the vitality of a culture depends on the strength of its positive images of the future. Futures work examines whose images dominate and how alternative images can be cultivated.","references":[{"content":"Polak, F. (1973). The Image of the Future. Amsterdam: Elsevier."}]},"ar":{"name":"صورة المستقبل","briefDescription":"تصور مشترك لما هو آتٍ يشكّل طريقة تصرّف المجتمع في الحاضر.","fullDescription":"رأى فريد بولاك أن حيوية الثقافة تتوقف على قوة صورها الإيجابية عن المستقبل، ويدرس العمل المستقبلي صورَ من تهيمن وكيف يمكن تنمية صور بديلة."}},"more":[]}' AS JSON)),
(34, 6, 'published', 0, CAST('{"default":{"en":{"name":"Used Future","briefDescription":"An image of the future borrowed from others that no longer fits the needs or values of those who hold it.","fullDescription":"Sohail Inayatullah uses the term for visions adopted uncritically, such as copying another region\'s development path. Identifying used futures is a first step towards imagining futures of one\'s own."},"ar":{"name":"المستقبل المستعمَل","briefDescription":"صورة للمستقبل مستعارة من الآخرين لم تعد تلائم احتياجات أصحابها أو قيمهم.","fullDescription":"يستخدم سهيل عناية الله المصطلح لوصف الرؤى المتبنّاة دون تمحيص، كاستنساخ مسار تنمية منطقة أخرى، ويُعد تحديد المستقبلات المستعمَلة خطوة أولى نحو تخيّل مستقبلات خاصة بنا."}},"more":[]}' AS JSON)),
(35, 3, 'published', 0, CAST('{"default":{"en":{"name":"Tipping Point","briefDescription":"A threshold beyond which a small change triggers a large, often irreversible shift in a system.","fullDescription":"In climate science, tipping points include the loss of ice sheets or the dieback of rainforests. In social systems they describe moments when an idea or behaviour suddenly spreads widely."},"ar":{"name":"نقطة التحول","briefDescription":"عتبة يؤدي تجاوزها إلى أن يُحدث تغيير صغير تحولًا كبيرًا لا رجعة فيه غالبًا في نظام ما.","fullDescription":"في علم المناخ تشمل نقاط التحول ذوبان الصفائح الجليدية أو تدهور الغابات المطيرة، وفي الأنظمة الاجتماعية تصف اللحظات التي تنتشر فيها فكرة أو سلوك فجأة على نطاق واسع."}},"more":[]}' AS JSON)),
(36, 1, 'published', 0, CAST('{"default":{"en":{"name":"Technological Singularity","briefDescription":"A hypothetical point at which technological growth, often driven by superintelligent AI, becomes uncontrollable and irreversible.","fullDescription":"The idea suggests that beyond such a point the future would be impossible to predict from today\'s vantage. It is debated as both a serious scenario and a speculative narrative.","references":[{"content":"Vinge, V. (1993). The coming technological singularity. Whole Earth Review, 81, 88–95."}]},"ar":{"name":"التفرد التكنولوجي","briefDescription":"نقطة افتراضية يصبح عندها النمو التكنولوجي، المدفوع غالبًا بذكاء اصطناعي فائق، خارجًا عن السيطرة ولا رجعة فيه.","fullDescription":"تفترض الفكرة أن المستقبل بعد تلك النقطة سيستحيل التنبؤ به انطلاقًا من موقعنا اليوم، ويدور حولها جدل بين من يعدّها سيناريو جادًا ومن يراها سردية تأملية."}},"more":[]}' AS JSON)),
(37, 1, 'published', 0, CAST('{"default":{"en":{"name":"Digital Twin","briefDescription":"A virtual model of a physical object, system or city that is updated with real-world data to simulate and predict its behaviour.","fullDescription":"Digital twins let planners test interventions, such as new traffic rules or maintenance schedules, before applying them in reality. They are increasingly used in infrastructure, manufacturing and urban planning."},"ar":{"name":"التوأم الرقمي","briefDescription":"نموذج افتراضي لشيء أو نظام أو مدينة يُحدَّث ببيانات من العالم الحقيقي لمحاكاة سلوكه والتنبؤ به.","fullDescription":"تتيح التوائم الرقمية للمخططين اختبار التدخلات، مثل قواعد مرور جديدة أو جداول صيانة، قبل تطبيقها في الواقع، ويتزايد استخدامها في البنية التحتية والتصنيع والتخطيط العمراني."}},"more":[]}' AS JSON)),
(38, 3, 'published', 0, CAST('{"default":{"en":{"name":"Synthetic Biology","briefDescription":"A field that designs and constructs new biological parts, devices and systems, or redesigns existing ones.","fullDescription":"Synthetic biology could transform medicine, agriculture and materials, but it also raises questions of biosafety, biosecurity and equitable access that foresight helps to anticipate."},"ar":{"name":"البيولوجيا التركيبية","briefDescription":"مجال يصمّم ويبني أجزاء وأجهزة وأنظمة بيولوجية جديدة، أو يعيد تصميم الموجود منها.","fullDescription":"قد تُحدث البيولوجيا التركيبية تحولًا في الطب والزراعة والمواد، لكنها تثير أيضًا قضايا السلامة الحيوية والأمن الحيوي وعدالة الوصول التي يساعد الاستشراف على استباقها."}},"more":[]}' AS JSON)),
(39, 3, 'published', 0, CAST('{"default":{"en":{"name":"Quantum Computing","briefDescription":"Computing that uses quantum phenomena such as superposition and entanglement to process information in fundamentally new ways.","fullDescription":"Quantum computers could solve certain problems, in cryptography, chemistry and optimisation, far faster than classical machines. Their timeline remains uncertain, making them a frequent subject of technology foresight."},"ar":{"name":"الحوسبة الكمومية","briefDescription":"حوسبة تستخدم ظواهر كمومية مثل التراكب والتشابك لمعالجة المعلومات بطرق جديدة جذريًا.","fullDescription":"قد تحل الحواسيب الكمومية مشكلات معينة في التشفير والكيمياء والتحسين أسرع بكثير من الحواسيب التقليدية، ويظل أفقها الزمني غير مؤكد مما يجعلها موضوعًا متكررًا في الاستشراف التكنولوجي."}},"more":[]}' AS JSON)),
(40, 2, 'published', 0, CAST('{"default":{"en":{"name":"Smart City","briefDescription":"An urban area that uses digital technology and data to improve services, infrastructure and quality of life.","fullDescription":"Smart city initiatives range from sensor-based traffic management to digital public services. Foresight asks who benefits, how privacy is protected and how such cities remain inclusive over time."},"ar":{"name":"المدينة الذكية","briefDescription":"منطقة حضرية تستخدم التقنيات الرقمية والبيانات لتحسين الخدمات والبنية التحتية وجودة الحياة.","fullDescription":"تتراوح مبادرات المدن الذكية بين إدارة المرور القائمة على أجهزة الاستشعار والخدمات العامة الرقمية، ويسأل الاستشراف عن المستفيدين منها وكيفية حماية الخصوصية وضمان بقاء هذه المدن شاملة للجميع."}},"more":[]}' AS JSON)),
(41, 2, 'published', 0, CAST('{"default":{"en":{"name":"Circular Economy","briefDescription":"An economic model that keeps materials in use for as long as possible by designing out waste and regenerating natural systems.","fullDescription":"In contrast to the linear \'take, make, dispose\' model, a circular economy emphasises reuse, repair, remanufacturing and recycling. It is a key pathway in many sustainability scenarios."},"ar":{"name":"الاقتصاد الدائري","briefDescription":"نموذج اقتصادي يُبقي المواد قيد الاستخدام أطول مدة ممكنة عبر تصميم يستبعد الهدر ويجدّد الأنظمة الطبيعية.","fullDescription":"على النقيض من النموذج الخطي «خذ، اصنع، تخلّص»، يركّز الاقتصاد الدائري على إعادة الاستخدام والإصلاح وإعادة التصنيع والتدوير، وهو مسار أساسي في كثير من سيناريوهات الاستدامة."}},"more":[]}' AS JSON)),
(42, 3, 'published', 0, CAST('{"default":{"en":{"name":"Climate Adaptation","briefDescription":"Adjusting societies, economies and ecosystems to actual or expected climate change to reduce harm and seize opportunities.","fullDescription":"Adaptation includes measures such as resilient infrastructure, water management and changes in agriculture. Because climate impacts unfold over decades, adaptation planning relies heavily on scenarios and long-term foresight."},"ar":{"name":"التكيّف المناخي","briefDescription":"تكييف المجتمعات والاقتصادات والنظم البيئية مع تغيّر المناخ الفعلي أو المتوقع للحد من الأضرار واغتنام الفرص.","fullDescription":"يشمل التكيّف تدابير مثل البنية التحتية المرنة وإدارة المياه وتغيير الممارسات الزراعية، ولأن آثار المناخ تتكشف على مدى عقود يعتمد التخطيط للتكيّف اعتمادًا كبيرًا على السيناريوهات والاستشراف بعيد المدى."}},"more":[]}' AS JSON)),
(43, 2, 'published', 0, CAST('{"default":{"en":{"name":"Universal Basic Income","briefDescription":"A regular cash payment given to all individuals without conditions, regardless of income or employment.","fullDescription":"UBI is discussed as a response to automation, inequality and changing work. Pilots in several countries have explored its effects, and it features in many scenarios about the future of work."},"ar":{"name":"الدخل الأساسي الشامل","briefDescription":"مبلغ نقدي منتظم يُمنح لجميع الأفراد دون شروط، بغض النظر عن دخلهم أو عملهم.","fullDescription":"يُطرح الدخل الأساسي الشامل استجابةً للأتمتة وعدم المساواة وتحولات العمل، وقد اختبرت تجارب في عدة دول آثاره، ويحضر في كثير من السيناريوهات حول مستقبل العمل."}},"more":[]}' AS JSON)),
(44, 2, 'pending', 0, CAST('{"default":{"en":{"name":"Algorithmic Governance","briefDescription":"The use of algorithms and automated systems to inform or make decisions in public administration and regulation.","fullDescription":"Algorithmic governance promises efficiency and consistency but raises concerns about transparency, accountability and bias. Its future depends on how societies choose to oversee automated decision-making."},"ar":{"name":"الحوكمة الخوارزمية","briefDescription":"استخدام الخوارزميات والأنظمة المؤتمتة لتوجيه القرارات أو اتخاذها في الإدارة العامة والتنظيم.","fullDescription":"تعد الحوكمة الخوارزمية بالكفاءة والاتساق، لكنها تثير مخاوف تتعلق بالشفافية والمساءلة والتحيز، ويتوقف مستقبلها على الطريقة التي تختارها المجتمعات للإشراف على القرارات المؤتمتة."}},"more":[]}' AS JSON)),
(45, 1, 'published', 0, CAST('{"default":{"en":{"name":"Decentralized Autonomous Organization (DAO)","briefDescription":"An organisation governed by rules encoded on a blockchain, where members vote on decisions without central management.","fullDescription":"DAOs experiment with new forms of collective ownership and coordination. Their legal status, security and long-term viability are still being tested, making them a recurring theme in futures of governance."},"ar":{"name":"المنظمة اللامركزية المستقلة","briefDescription":"منظمة تُدار بقواعد مبرمجة على سلسلة الكتل، يصوّت أعضاؤها على القرارات دون إدارة مركزية.","fullDescription":"تجرّب المنظمات اللامركزية المستقلة أشكالًا جديدة من الملكية والتنسيق الجماعي، ولا يزال وضعها القانوني وأمنها وجدواها على المدى البعيد قيد الاختبار، مما يجعلها موضوعًا متكررًا في مستقبلات الحوكمة."}},"more":[]}' AS JSON)),
(46, 2, 'pending', 0, CAST('{"default":{"en":{"name":"Resilience","briefDescription":"The capacity of a system, community or organisation to absorb shocks, adapt and continue to function.","fullDescription":"Resilience thinking shifts attention from predicting specific events to strengthening the ability to cope with many possible disruptions. It is closely linked to foresight practices such as wind tunnelling."},"ar":{"name":"المرونة","briefDescription":"قدرة نظام أو مجتمع أو مؤسسة على امتصاص الصدمات والتكيّف ومواصلة العمل.","fullDescription":"يحوّل التفكير في المرونة الاهتمام من التنبؤ بأحداث بعينها إلى تعزيز القدرة على التعامل مع اضطرابات ممكنة عديدة، وهو وثيق الصلة بممارسات استشرافية مثل اختبار نفق الرياح."}},"more":[]}' AS JSON)),
(47, 2, 'published', 0, CAST('{"default":{"en":{"name":"Sustainable Development","briefDescription":"Development that meets the needs of the present without compromising the ability of future generations to meet their own needs.","fullDescription":"This definition from the 1987 Brundtland Report places intergenerational responsibility at the heart of policy. The UN Sustainable Development Goals translate it into targets for 2030.","references":[{"content":"World Commission on Environment and Development. (1987). Our Common Future. Oxford: Oxford University Press."}]},"ar":{"name":"التنمية المستدامة","briefDescription":"تنمية تلبي احتياجات الحاضر دون المساس بقدرة الأجيال القادمة على تلبية احتياجاتها.","fullDescription":"يضع هذا التعريف الوارد في تقرير برونتلاند عام 1987 المسؤوليةَ بين الأجيال في صميم السياسات، وتترجمه أهداف الأمم المتحدة للتنمية المستدامة إلى غايات لعام 2030."}},"more":[]}' AS JSON)),
(48, 5, 'published', 0, CAST('{"default":{"en":{"name":"Systems Thinking","briefDescription":"An approach that understands problems as parts of interconnected wholes, focusing on relationships, feedback loops and delays.","fullDescription":"Systems thinking helps foresight practitioners see how drivers interact and why interventions can have unintended consequences. Tools include causal loop diagrams and stock-and-flow models."},"ar":{"name":"التفكير المنظومي","briefDescription":"مقاربة تفهم المشكلات بوصفها أجزاء من كلٍّ مترابط، مع التركيز على العلاقات وحلقات التغذية الراجعة والتأخيرات.","fullDescription":"يساعد التفكير المنظومي ممارسي الاستشراف على رؤية كيفية تفاعل المحركات ولماذا قد تؤدي التدخلات إلى عواقب غير مقصودة، ومن أدواته مخططات الحلقات السببية ونماذج المخزون والتدفق."}},"more":[]}' AS JSON)),
(49, 6, 'published', 0, CAST('{"default":{"en":{"name":"Futures Studies","briefDescription":"The interdisciplinary field that systematically explores possible, probable and preferable futures and the worldviews behind them.","fullDescription":"Futures studies draws on the social sciences, systems thinking and creative practice. Rather than predicting a single future, it maps alternatives and helps people shape the futures they want.","references":[{"content":"Bell, W. (1997). Foundations of Futures Studies: Human Science for a New Era. New Brunswick, NJ: Transaction Publishers."}]},"ar":{"name":"دراسات المستقبلات","briefDescription":"حقل متعدد التخصصات يستكشف بصورة منهجية المستقبلات الممكنة والمحتملة والمفضّلة والرؤى الكونية التي تقف خلفها.","fullDescription":"تستند دراسات المستقبلات إلى العلوم الاجتماعية والتفكير المنظومي والممارسة الإبداعية، ولا تسعى إلى التنبؤ بمستقبل واحد بل ترسم البدائل وتساعد الناس على صنع المستقبلات التي يريدونها."}},"more":[]}' AS JSON));
